\begin{aligned}
\operatorname{acl}_{\mathfrak A}(Y)
&:=\{a\in|\mathfrak A|:\exists E\in\operatorname{UnDef}_1(\mathfrak A;Y)\;(\mathrm{Finite}(E)\land a\in E)\},\\
\operatorname{cl}_{\mathfrak A,D,C}(X)&:=D\cap\operatorname{acl}_{\mathfrak A}(C\cup X)\quad(X\subseteq D),\\
\operatorname{Ind}_{\mathfrak A,D,C}(X)
&\leftrightarrow X\subseteq D\land\forall a\in X\;
\bigl(a\notin\operatorname{cl}_{\mathfrak A,D,C}(X\setminus\{a\})\bigr),\\
\operatorname{Basis}_{\mathfrak A,D,C}(X)
&\leftrightarrow\operatorname{Ind}_{\mathfrak A,D,C}(X)\land\operatorname{cl}_{\mathfrak A,D,C}(X)=D.
\end{aligned}
